import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { AlertsButton } from '@/components/AlertsButton'
import { DecisionList, visibleOrder } from '@/components/DecisionList'
import { DecisionPane, type Offer } from '@/components/DecisionPane'
import { EvidenceDrawer, type DrawerView } from '@/components/EvidenceDrawer'
import { Header, VerdictLine, type View } from '@/components/Header'
import { LaunchTimeline } from '@/components/LaunchTimeline'
import { Routines } from '@/components/Routines'
import { SupplyMap, type MapSelection } from '@/components/SupplyMap'
import { COLORS, DECIDED, ago, fetchState, viaOf, type Card, type State } from '@/lib/api'
import { groupKey, sections } from '@/lib/decisions'

const POLL_MS = 5000

function usePhone() {
  const q = '(max-width: 767px)'
  const [phone, setPhone] = useState(() => window.matchMedia(q).matches)
  useEffect(() => {
    const m = window.matchMedia(q)
    const on = () => setPhone(m.matches)
    m.addEventListener('change', on)
    return () => m.removeEventListener('change', on)
  }, [])
  return phone
}

const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))

export default function App() {
  const [state, setState] = useState<State | null>(null)
  const [error, setError] = useState(false)
  const [nowMs, setNowMs] = useState(Date.now())
  const [view, setView] = useState<View>('launch')
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [expanded, setExpanded] = useState<Set<string>>(new Set())
  const [mapSel, setMapSel] = useState<MapSelection>({})
  const [drawer, setDrawer] = useState<DrawerView>(null)
  const [toast, setToast] = useState<string | null>(null)
  const [pulseNode, setPulseNode] = useState<string | null>(null)
  const [fresh, setFresh] = useState<Set<string>>(new Set())
  const seenEvents = useRef<Set<string> | null>(null)
  const seenCards = useRef<Set<string> | null>(null)
  // A card that was just decided (button or voice): offer to automate the next one like it.
  const lastStatus = useRef<Map<string, string> | null>(null)
  const [justDecided, setJustDecided] = useState<Card | null>(null)
  const [automate, setAutomate] = useState<{ cardId: string; k: number } | null>(null)
  // A decision without an offer moves the selection on to the next one.
  const [advance, setAdvance] = useState<{ id: string; k: number } | null>(null)
  const offset = useRef(0)
  const phone = usePhone()
  const [path, setPath] = useState(window.location.pathname)
  // Opened from a push alert (/d/<id>?talk=1): show the card as an incoming call.
  const [ringing, setRinging] = useState(new URLSearchParams(window.location.search).get('talk') === '1')
  const stopRinging = () => {
    setRinging(false)
    window.history.replaceState(null, '', window.location.pathname)
  }
  const go = (to: string) => {
    window.history.pushState(null, '', to)
    setPath(to)
    window.scrollTo(0, 0)
  }

  const load = useCallback(async () => {
    try {
      const s = await fetchState()
      offset.current = new Date(s.now).getTime() - Date.now()
      setNowMs(Date.now() + offset.current)
      setState(s)
      setError(false)

      // A new portal drop: say the agents are reading it (and pulse its place on the map).
      const ev = new Set(s.events.map((e) => e.id))
      if (seenEvents.current) {
        const added = s.events.filter((e) => !seenEvents.current!.has(e.id))
        if (added.length) {
          const e = added[0]
          const name = (e.path || e.file || '').split('/').pop()
          setToast(`New: ${name}. Agent reading…`)
          setPulseNode(e.node ?? null)
          window.setTimeout(() => setToast(null), 5000)
          window.setTimeout(() => setPulseNode(null), 4500)
        }
      }
      seenEvents.current = ev

      const ids = new Set(s.cards.filter((c) => c.status === 'open').map((c) => c.id))
      if (seenCards.current) {
        const added = [...ids].filter((id) => !seenCards.current!.has(id))
        if (added.length) {
          setFresh((f) => new Set([...f, ...added]))
          window.setTimeout(() => setFresh((f) => new Set([...f].filter((x) => !added.includes(x)))), 2500)
        }
      }
      seenCards.current = ids

      const prev = lastStatus.current
      if (prev) {
        const done = s.cards.find((c) => prev.get(c.id) === 'open' && DECIDED.includes(c.status))
        // Not when a routine made the decision, nor when a routine already covers this card.
        const byRoutine = (c: Card) => s.activity.some((a) => a.card === c.id && viaOf(a)?.kind === 'routine')
        if (done) {
          if (!byRoutine(done) && !(await hasRoutine(done.id))) setJustDecided(done)
          else setAdvance({ id: done.id, k: Date.now() })
        }
      }
      lastStatus.current = new Map(s.cards.map((c) => [c.id, c.status]))
    } catch {
      setError(true)
    }
  }, [])

  useEffect(() => {
    load()
    const poll = window.setInterval(load, POLL_MS)
    const tick = window.setInterval(() => setNowMs(Date.now() + offset.current), 15000)
    const nav = () => setPath(window.location.pathname)
    window.addEventListener('popstate', nav)
    return () => { clearInterval(poll); clearInterval(tick); window.removeEventListener('popstate', nav) }
  }, [load])

  const sec = useMemo(() => (state ? sections(state) : null), [state])
  const order = useMemo(() => (sec ? visibleOrder(sec, expanded) : []), [sec, expanded])
  const needsOrder = useMemo(() => (sec ? sec.needs.flatMap((g) => g.cards.map((c) => c.id)) : []), [sec])
  const lastOrder = useRef<string[]>([])
  const touched = useRef(false)

  const select = useCallback((id: string | null) => {
    touched.current = true
    setSelectedId(id)
    if (!id || !sec) return
    // A card hidden in a closed group (from the timeline, say): open its group.
    const g = sec.needs.find((x) => x.cards.length > 1 && x.lead.id !== id && x.cards.some((c) => c.id === id))
    if (g) setExpanded((e) => new Set([...e, g.key]))
    window.setTimeout(() => document.getElementById(`row-${id}`)?.scrollIntoView({ block: 'nearest' }), 0)
  }, [sec])

  // Keep the selection across polls; if its card is gone, take the one that moved into its place.
  useEffect(() => {
    if (!state) return
    const exists = selectedId && state.cards.some((c) => c.id === selectedId)
    if (!exists) {
      if (selectedId) {
        const i = lastOrder.current.indexOf(selectedId)
        const next = lastOrder.current.slice(i + 1).find((id) => order.includes(id)) ?? order[order.length - 1] ?? null
        setSelectedId(next)
      } else if (!touched.current && order.length && needsOrder.length) {
        setSelectedId(order[0])
      }
    }
    lastOrder.current = order
  }, [state, order, needsOrder, selectedId])

  const nextOpen = useCallback((from: string) => {
    const i = lastOrder.current.indexOf(from)
    const after = lastOrder.current.slice(i + 1).find((id) => needsOrder.includes(id) && id !== from)
    return after ?? needsOrder.find((id) => id !== from) ?? null
  }, [needsOrder])

  useEffect(() => {
    if (advance && advance.id === selectedId) select(nextOpen(advance.id))
    // only when a new decision lands
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [advance])

  // j / k / arrows walk the list.
  useEffect(() => {
    if (phone || view !== 'launch' || path !== '/') return
    const onKey = (e: KeyboardEvent) => {
      if (typing(e.target) || e.metaKey || e.ctrlKey || e.altKey || drawer) return
      const k = e.key
      const down = k === 'j' || k === 'J' || k === 'ArrowDown'
      const up = k === 'k' || k === 'K' || k === 'ArrowUp'
      if (!down && !up) return
      e.preventDefault()
      const i = selectedId ? order.indexOf(selectedId) : -1
      const n = i < 0 ? 0 : Math.min(order.length - 1, Math.max(0, i + (down ? 1 : -1)))
      if (order[n]) select(order[n])
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [phone, view, path, order, selectedId, select, drawer])

  const openDrawer = useCallback((card: Card, tab: 'evidence' | 'trail') => setDrawer({ card, tab }), [])
  const automateFrom = (card: Card) => { setAutomate({ cardId: card.id, k: Date.now() }); setJustDecided(null) }

  if (!state || !sec) {
    return <div className="grid h-full place-items-center text-ink-3">{error ? 'Cannot reach the server.' : 'Loading…'}</div>
  }

  const groupOf = (c: Card) => sec.needs.find((g) => g.cards.some((x) => x.id === c.id)) ?? null
  const offerFor = (c: Card): Offer | null => {
    if (justDecided?.id !== c.id) return null
    const k = groupKey(c)
    return {
      more: state.cards.filter((x) => x.id !== c.id && x.status === 'open' && groupKey(x) === k).length,
      onYes: () => automateFrom(c),
      onNext: () => { setJustDecided(null); select(nextOpen(c.id)) },
    }
  }
  const routines = <Routines state={state} onChanged={load} request={automate} />

  // ------------------------------------------------------------ one decision (/d/<id>)
  const single = path.match(/^\/d\/(.+)$/)
  if (single) {
    const id = decodeURIComponent(single[1])
    const card = state.cards.find((c) => c.id === id)
    return (
      <div className="min-h-full bg-white">
        <div className="sticky top-0 z-20 flex h-14 items-center justify-between gap-3 border-b border-line bg-white/95 px-4 backdrop-blur">
          <button onClick={() => go('/')} className="cursor-pointer text-sm font-semibold text-ok hover:underline">← All decisions</button>
          <div className="flex items-center gap-2">{routines}<AlertsButton /></div>
        </div>
        <main className="mx-auto max-w-[900px] px-4 py-6 sm:px-8">
          {card ? (
            <DecisionPane
              key={card.id}
              card={card}
              state={state}
              nowMs={nowMs}
              group={groupOf(card)}
              direct
              onChanged={load}
              onDrawer={openDrawer}
              ringing={ringing && card.status === 'open'}
              onRingingDone={stopRinging}
              offer={offerFor(card) && { ...offerFor(card)!, onNext: () => { setJustDecided(null); const n = nextOpen(card.id); go(n ? `/d/${encodeURIComponent(n)}` : '/') } }}
            />
          ) : (
            <p className="text-ink-2">This decision is no longer open.</p>
          )}
        </main>
        <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
      </div>
    )
  }

  const selected = selectedId ? state.cards.find((c) => c.id === selectedId) ?? null : null
  const openOnPhone = (id: string) => go(`/d/${encodeURIComponent(id)}`)
  const timeline = (
    <LaunchTimeline
      state={state}
      nowMs={nowMs}
      selectedId={selectedId}
      onSelect={(id) => (phone ? openOnPhone(id) : select(id))}
      compact={phone}
    />
  )
  const header = (
    <Header state={state} nowMs={nowMs} view={view} onView={setView} routines={routines} bell={<AlertsButton />} compact={phone} />
  )
  const toggle = (key: string) =>
    setExpanded((e) => { const n = new Set(e); if (n.has(key)) n.delete(key); else n.add(key); return n })
  const list = (
    <DecisionList
      state={state}
      nowMs={nowMs}
      sec={sec}
      selectedId={phone ? null : selectedId}
      onSelect={phone ? openOnPhone : select}
      expanded={expanded}
      onToggle={toggle}
      fresh={fresh}
    />
  )
  const suppliers = (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="relative min-h-[420px] flex-1">
        <SupplyMap state={state} hoverRoutes={[]} selection={mapSel} onSelect={setMapSel} pulseNode={pulseNode} />
      </div>
      <Legend />
    </div>
  )
  const overlays = (
    <>
      {toast && (
        <div className="toast-in fixed left-1/2 top-20 z-50 -translate-x-1/2 rounded-xl border border-line bg-white px-5 py-3 text-[15px] font-semibold shadow-lg">
          <span className="mr-2 inline-block h-2.5 w-2.5 animate-pulse rounded-full bg-ok" />
          {toast}
        </div>
      )}
      <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
    </>
  )

  // ------------------------------------------------------------ phone
  if (phone) {
    return (
      <div className="flex min-h-full flex-col bg-white">
        <div className="sticky top-0 z-20">{header}</div>
        {view === 'launch' ? (
          <>
            <VerdictLine state={state} nowMs={nowMs} />
            <div className="border-b border-line">{timeline}</div>
            <div className="px-1">{list}</div>
          </>
        ) : suppliers}
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ desktop
  const openCount = sec.needs.length
  return (
    <div className="flex h-full flex-col bg-white">
      {header}
      {view === 'launch' ? (
        <>
          <div className="shrink-0 border-b border-line">{timeline}</div>
          <div className="flex min-h-0 flex-1">
            <aside className="scroll-thin w-[372px] shrink-0 overflow-y-auto border-r border-line px-2" aria-label="Decisions">
              {list}
            </aside>
            <main className="scroll-thin min-w-0 flex-1 overflow-y-auto">
              <div className="mx-auto max-w-[900px] px-8 py-8 xl:px-12">
                {selected ? (
                  <DecisionPane
                    key={selected.id}
                    card={selected}
                    state={state}
                    nowMs={nowMs}
                    group={groupOf(selected)}
                    keys
                    onChanged={load}
                    onDrawer={openDrawer}
                    offer={offerFor(selected)}
                  />
                ) : (
                  <div className="grid min-h-[40vh] place-items-center text-center">
                    {openCount === 0 ? (
                      <p className="max-w-md text-[16px] leading-relaxed text-ink-2">
                        <span className="block text-[20px] font-bold text-ink">Nothing needs you.</span>
                        Agents are watching {state.shipments.length} shipments; last check {ago(state.last_check_at, nowMs)}.
                      </p>
                    ) : (
                      <p className="text-[16px] text-ink-2">Pick a decision, or press <kbd>J</kbd>.</p>
                    )}
                  </div>
                )}
              </div>
            </main>
          </div>
        </>
      ) : suppliers}
      {overlays}
    </div>
  )
}

// A routine already written from this card: do not offer to automate it again.
async function hasRoutine(cardId: string): Promise<boolean> {
  try {
    const r = await fetch('/api/routines')
    if (!r.ok) return false
    const { routines } = (await r.json()) as { routines: { created_from?: string }[] }
    return routines.some((x) => x.created_from === cardId)
  } catch {
    return false
  }
}

function Legend() {
  const sw = (c: string, label: string) => (
    <span className="inline-flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-full" style={{ background: c }} />{label}</span>
  )
  const line = (dash: boolean, label: string) => (
    <span className="inline-flex items-center gap-1.5">
      <svg width="26" height="6"><line x1="1" y1="3" x2="25" y2="3" stroke="#475569" strokeWidth="2.5" strokeDasharray={dash ? '6 4' : undefined} strokeLinecap="round" /></svg>
      {label}
    </span>
  )
  return (
    <div className="flex flex-wrap items-center gap-x-5 gap-y-1 border-t border-line px-5 py-3 text-sm text-ink-2">
      {line(false, 'Air / truck')}
      {line(true, 'Sea')}
      <span className="h-4 w-px bg-line" />
      {sw(COLORS.blue, 'On track')}
      {sw(COLORS.amber, 'At risk')}
      {sw(COLORS.red, 'Stops a line')}
      {sw(COLORS.grey, 'Silent')}
    </div>
  )
}
export type Level = 'red' | 'amber' | 'grey' | 'blue'

export interface Option {
  index: number
  action?: string
  cost?: string
  effect?: string
  recommended: boolean
  draft?: string
  to?: string
  channel?: string
  routine_type?: string | null
}
export interface Evidence {
  source?: string
  value?: string | number
  doc?: string
  page?: number
  quote?: string
  translation?: string
  language?: string
  unit?: string
}
export interface TrailStep { agent?: string; at?: string; text?: string }

export interface Card {
  id: string
  kind?: string
  part?: string
  /** Short readable name of the part code, from the master data ("Art Book"). */
  part_name?: string | null
  headline: string
  summary?: string
  number: number | null
  number_label: string
  edition?: string
  cell_hours_lost?: number
  slack_hours?: number
  deadline?: string
  runs_dry?: string | null
  /** When the late goods arrive, if a finding states it (may be after launch). */
  arrives_at?: string | null
  severity?: string
  level: Level
  status: string
  approver?: string
  routed_to_other: boolean
  reason?: string
  called_at?: string
  options: Option[]
  evidence: Evidence[]
  trail: TrailStep[]
  supplier_id?: string
  supplier_name?: string
  shipment?: string
  routes: string[]
  ui: {
    status?: string; at?: string; note?: string
    // Supplier reply tied back by the alert agent (replies.py)
    reply?: string; reply_from?: string; reply_at?: string; reply_text?: string
    /** Facts read from the reply: the date and quantity the supplier commits to. */
    reply_date?: string | null; reply_quantity?: number | string | null; reply_after_launch?: boolean | null
  }
  escalation_brief: string
}

export interface MapNode { id: string; kind: 'supplier' | 'port' | 'dc' | 'site'; name: string; lat: number; lon: number; country?: string }
export interface Leg { id: string; origin: string; destination: string; mode: string; via?: string; path: [number, number][] | null }
export interface Shipment {
  id: string; route_id: string; mode: string; supplier_id: string; status: string
  eta?: string; etd?: string; progress: number; departed: boolean; silent: boolean; silent_hours?: number
  level: Level; note?: string
}
export interface StripItem {
  edition: string; label: string; level: Level; status: string
  copies_at_risk: number; slack_hours: number | null
  breaks_first: { text?: string; deadline?: string; stops_at?: string | null; card: string } | null
  finishes_at?: string | null
  stops_at?: string | null
}

/** One edition on the packing clock: when its line finishes, or stops for want of parts. */
export interface ClockEdition {
  edition: string
  label: string
  level: Level
  /** Last copy packed at plan rate; null if the line stops first or the shifts run out. */
  finishes_at: string | null
  /** Line runs out of parts (projected; never at night); null if it does not stop. */
  stops_at: string | null
  /** Largest copies-at-risk figure on the edition's open cards, or the verifier's if higher. */
  copies_at_risk: number
  slack_hours: number | null
  remaining: number | null
  rate_per_hour: number | null
  /** When the packed count behind `remaining` was taken; packing is projected at plan rate since. */
  packed_as_of: string | null
  /** Copies the hours left cannot pack even with every part present. */
  short_of_time: number | null
  breaks_first_card: string | null
}
export interface Clock {
  /** Trucks leave: the end of the last shift. */
  launch: string
  /** Shift windows [start, end] from the start of today until launch, ISO. */
  windows: [string, string][]
  editions: ClockEdition[]
}
export interface EventItem { id: string; at: string; path?: string; file?: string; node?: string }
export interface ActivityItem {
  at?: string; text: string; kind: string; detail?: string | null; card?: string
  /** Who handled it: "inbox", "voice" or "routine: <name>". Missing on older items. */
  via?: string | null
  /** The action behind it, for undo (POST /api/routines/actions/{id}/undo). Missing: no undo. */
  action_id?: string | null
  id?: string | null
}

export interface State {
  now: string
  viewer: string
  portal_found: boolean
  map: { nodes: MapNode[]; legs: Leg[]; version: string }
  route_level: Record<string, Level>
  badges: Record<string, number>
  shipments: Shipment[]
  strip: StripItem[]
  clock?: Clock
  cards: Card[]
  inbox_ids: string[]
  calm: boolean
  events: EventItem[]
  activity: ActivityItem[]
  last_drop_at: string | null
  last_check_at: string | null
  read_since_6: number
  trust: Record<string, string>
}

export async function fetchState(): Promise<State> {
  const r = await fetch('/api/state')
  if (!r.ok) throw new Error(`state ${r.status}`)
  return r.json()
}

export async function post<T = unknown>(url: string, body: unknown = {}): Promise<T> {
  const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  if (!r.ok) throw new Error(`${url} ${r.status}`)
  return r.json()
}

export const COLORS: Record<Level, string> = {
  blue: '#1d6fe0',
  amber: '#d97706',
  red: '#dc2626',
  grey: '#7b8494',
}
export const LEVEL_RANK: Record<Level, number> = { red: 3, amber: 2, grey: 1, blue: 0 }

const TZ = 'Europe/Berlin'
export const fmtTime = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtDay = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { weekday: 'short', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtNum = (n: number | null | undefined) => (n == null ? '–' : Math.round(n).toLocaleString('en-GB'))

export function ago(iso: string | null | undefined, nowMs: number): string {
  if (!iso) return 'never'
  const min = Math.max(0, Math.round((nowMs - new Date(iso).getTime()) / 60000))
  if (min < 1) return 'just now'
  if (min < 60) return `${min} min ago`
  const h = Math.floor(min / 60)
  return h < 48 ? `${h} h ago` : `${Math.floor(h / 24)} days ago`
}

export function until(iso: string | undefined, nowMs: number): { text: string; urgent: boolean } | null {
  if (!iso) return null
  const min = Math.round((new Date(iso).getTime() - nowMs) / 60000)
  if (min <= 0) return { text: 'now', urgent: true }
  const text = min < 60 ? `${min} min` : `${Math.floor(min / 60)} h ${min % 60 ? `${min % 60} min` : ''}`.trim()
  return { text: `in ${text}`, urgent: min < 180 }
}

export const DONE_WORD: Record<string, string> = {
  approved: 'Approved', sent: 'Sent', escalated: 'Escalated', dismissed: 'Dismissed',
}
export const DECIDED = Object.keys(DONE_WORD)

/** What handled an activity item, read from its `via` field. */
export function viaOf(a: ActivityItem): { kind: 'routine'; name: string } | { kind: 'voice' } | null {
  const v = (a.via ?? '').trim()
  if (/^routine\s*:/i.test(v)) return { kind: 'routine', name: v.replace(/^routine\s*:\s*/i, '') }
  if (/^voice$/i.test(v)) return { kind: 'voice' }
  return null
}

// Internal part / product codes (CMP-GAM-001, FG-GH6-STD): never shown on their own.
const CODE = /^[A-Z]{2,5}(-[A-Z0-9]+)+$/

/** A readable name for a part code, found on the cards; undefined if none has one. */
export function partName(part: string | undefined, cards: Card[]): string | undefined {
  if (!part) return undefined
  if (!CODE.test(part)) return part
  const c = cards.find(
    (c) => c.part && !CODE.test(c.part) && (c.id.endsWith(part) || c.options.some((o) => o.action?.includes(`(${part})`))),
  )
  return c?.part
}

const fmtDate = (ymd: string) =>
  new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' }).format(
    new Date(`${ymd}T00:00:00Z`),
  )

/** Display text: drop bracketed internal codes, write ISO dates as "Mon 23 Nov". */
export function tidy(t: string | undefined | null): string {
  if (!t) return ''
  return t
    .replace(/\s*\((?:[A-Z]{2,5}-)+[A-Z0-9-]+\)/g, '')
    .replace(/\b(\d{4}-\d{2}-\d{2})(?:T[\d:.]+(?:Z|[+-]\d{2}:\d{2})?)?\b/g, (_, d: string) => fmtDate(d))
}

const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

/** One cost wording everywhere. */
export function costText(cost: string | undefined | null): string {
  const c = (cost ?? '').trim()
  if (!c || /^(none|no cost|free|0|-|–|n\/a)$/i.test(c)) return 'No cost'
  return cap(tidy(c))
}
export const sentence = (t: string | undefined | null) => cap(tidy(t))

/** Slack as people say it; "–" when it would only confuse (on track, or nothing at risk). */
export function slackText(hours: number | null, onTrack: boolean, atRisk: number): string {
  if (hours == null || (onTrack && (hours < 0 || atRisk === 0))) return '–'
  const sign = hours < 0 ? '−' : ''
  const a = Math.abs(hours)
  if (a < 1) return `${sign}${Math.round(a * 60)} min`
  return `${sign}${Math.round(a * 10) / 10} h`
}
// What the main screen derives from /api/state: the inbox sections, near-identical cards grouped
// into one row, the one-sentence launch verdict and the countdown to the trucks. Nothing here
// knows about a specific supplier, part or number: it all comes from the cards and the strip.

import {
  DECIDED, LEVEL_RANK, fmtDay, fmtNum, fmtTime, tidy, viaOf, type ActivityItem, type Card, type State, type StripItem,
} from '@/lib/api'

/** Several cards with the same problem (same supplier, same headline once numbers are removed). */
export interface Group {
  key: string
  cards: Card[]
  /** The card shown for the group: the most urgent one. */
  lead: Card
}

const shape = (t: string) => tidy(t).replace(/\d[\d,.' ]*\d|\d/g, '#').replace(/\s+/g, ' ').trim().toLowerCase()
export const groupKey = (c: Card) => `${c.supplier_id ?? c.supplier_name ?? ''}|${c.kind ?? ''}|${shape(c.headline)}`

const deadlineMs = (c: Card) => (c.deadline ? new Date(c.deadline).getTime() : Number.POSITIVE_INFINITY)
/** Most urgent first: earliest decide-by time, then the worse level, then the bigger number. */
export const byUrgency = (a: Card, b: Card) =>
  deadlineMs(a) - deadlineMs(b) || LEVEL_RANK[b.level] - LEVEL_RANK[a.level] || (b.number ?? 0) - (a.number ?? 0)

export function groupCards(cards: Card[]): Group[] {
  const map = new Map<string, Card[]>()
  for (const c of [...cards].sort(byUrgency)) {
    const k = groupKey(c)
    map.set(k, [...(map.get(k) ?? []), c])
  }
  return [...map.entries()].map(([key, cs]) => ({ key, cards: cs, lead: cs[0] }))
}

/** "PO 4500318774, 4500318765 and 4500318786": what differs between the cards of a group. */
export function sameIssueOn(g: Group): string | null {
  if (g.cards.length < 2) return null
  const first = tidy(g.lead.headline)
  const firstTokens = new Set(first.match(/\d[\d,.]*\d|\d/g) ?? [])
  const lead = [...firstTokens].find((t) => t.replace(/\D/g, '').length >= 4) ?? [...firstTokens][0]
  // The word in front of the lead's own number ("PO") names what the others are.
  const word = lead ? first.slice(0, first.indexOf(lead)).trim().split(/\s+/).pop() : undefined
  const others = g.cards.slice(1).map((c) => {
    const toks = tidy(c.headline).match(/\d[\d,.]*\d|\d/g) ?? []
    return toks.find((t) => !firstTokens.has(t)) ?? tidy(c.headline)
  })
  const list = others.length > 1 ? `${others.slice(0, -1).join(', ')} and ${others[others.length - 1]}` : others[0]
  return word && /^[A-Za-z]{1,12}$/.test(word) ? `${word} ${list}` : list
}

export const routineOf = (state: State, cardId: string): string | null => {
  const a = state.activity.find((x) => x.card === cardId && viaOf(x)?.kind === 'routine')
  const v = a ? viaOf(a) : null
  return v?.kind === 'routine' ? v.name : null
}

/** The action a routine took, for undo; null when the item carries no action id. */
export const actionIdOf = (a?: ActivityItem | null): string | null => (a ? a.action_id || a.id || null : null)
export const routineActionOf = (state: State, cardId: string): string | null =>
  actionIdOf(state.activity.find((x) => x.card === cardId && viaOf(x)?.kind === 'routine'))

const fmtLong = (iso: string) => {
  const d = new Date(/^\d{4}-\d{2}-\d{2}$/.test(iso) ? `${iso}T12:00:00Z` : iso)
  return Number.isNaN(d.getTime())
    ? tidy(iso)
    : new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Europe/Berlin' }).format(d)
}

/** "Hwaseong confirms 20,000 on Tue 24 Nov", plus whether that date misses the launch. */
export function replyFacts(card: Card): { text: string; late: boolean } | null {
  const u = card.ui ?? {}
  const qty = u.reply_quantity
  if (!u.reply_date && (qty == null || qty === '')) return null
