  return { text: `${who} confirms ${what}${u.reply_date ? ` on ${fmtLong(u.reply_date)}` : ''}`, late: u.reply_after_launch === true }
}

export interface Handled {
  key: string
  card?: Card
  text: string
  at?: string
  routine: string | null
  status?: string
  /** Set when the routine's action can be undone. */
  actionId?: string | null
