    <div className="whitespace-nowrap text-right leading-tight" title="Trucks leave Hamburg for retail">
      <div className="text-xs font-medium text-ink-3">{left > 0 ? 'Trucks in' : 'Trucks'}</div>
      <div className="text-[16px] font-bold tabular-nums">{left > 0 ? span(left) : 'have left'}</div>
    </div>
  )
}

function Tab({ on, onClick, children }: { on: boolean; onClick: () => void; children: ReactNode }) {
  return (
    <button
      onClick={onClick}
      aria-current={on ? 'page' : undefined}
      className={cn(
        'h-8 cursor-pointer rounded-md px-3 text-sm font-semibold',
        on ? 'bg-white text-ink shadow-sm ring-1 ring-line' : 'text-ink-2 hover:text-ink',
      )}
    >
      {children}
    </button>
  )
}

function PhoneMenu({ view, onView, routines }: { view: View; onView: (v: View) => void; routines: ReactNode }) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!open) return
    const off = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false) }
    document.addEventListener('mousedown', off)
    return () => document.removeEventListener('mousedown', off)
  }, [open])
  const item = (v: View, label: string) => (
    <button
      onClick={() => { onView(v); setOpen(false) }}
      className={cn('block w-full cursor-pointer rounded-lg px-3 py-2.5 text-left text-[15px] font-semibold hover:bg-panel', view === v ? 'text-ink' : 'text-ink-2')}
    >
      {label}
    </button>
  )
  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => setOpen(!open)}
        aria-label="Menu"
        aria-expanded={open}
        className="grid h-9 w-9 cursor-pointer place-items-center rounded-full border border-line bg-white text-ink-2 hover:bg-panel"
      >
        <Menu size={18} />
      </button>
      {/* Kept mounted so the Routines sheet survives the menu closing. */}
      <div className={cn('absolute right-0 top-11 z-30 w-52 rounded-xl border border-line bg-white p-1 shadow-lg', !open && 'hidden')}>
        {item('launch', 'Launch')}
        <div className="tab-routines-menu px-1 py-1" onClick={() => setOpen(false)}>{routines}</div>
        {item('suppliers', 'Suppliers')}
      </div>
    </div>
  )
}
import { Bell, BellRing } from 'lucide-react'
import { useEffect, useState } from 'react'
import { enableAlerts, pushSupported, registerServiceWorker, sendTestAlert } from '@/lib/push'

// Launch alerts on this device (web push). Independent of the cards on screen, so a fresh
// visit with an empty inbox can still turn them on.
export function AlertsButton() {
  const [on, setOn] = useState(false)
  const [info, setInfo] = useState('')
  const supported = pushSupported()

  useEffect(() => {
    void registerServiceWorker().then(async (reg) => {
      const sub = await reg?.pushManager.getSubscription()
      setOn(!!sub && Notification.permission === 'granted')
    })
  }, [])

  const say = (text: string) => {
    setInfo(text)
    window.setTimeout(() => setInfo(''), 6000)
  }

  return (
    <div className="relative">
      {info && (
        <div className="absolute right-0 top-11 z-50 w-72 rounded-xl border border-line bg-white px-4 py-2 text-sm text-ink-2 shadow-lg">{info}</div>
      )}
      <button
        className="inline-flex h-9 cursor-pointer items-center gap-2 whitespace-nowrap rounded-full border border-line bg-white px-2.5 text-sm 2xl:px-3.5 font-semibold text-ink-2 hover:bg-panel"
        onClick={async () => {
          if (!supported) return say('This browser cannot receive alerts. On iPhone: Share → Add to Home Screen, then open the app.')
          if (!on) {
            const text = await enableAlerts()
            setOn(text.startsWith('Alerts are on'))
            return say(text)
          }
          say(await sendTestAlert(''))
        }}
        title={on ? 'Send a test alert to this device' : 'Get launch alerts on this device'}
        aria-label={on ? 'Test alert' : 'Enable alerts'}
      >
        {on ? <BellRing size={16} className="text-ok" /> : <Bell size={16} />}
        <span className="hidden 2xl:inline">{on ? 'Test alert' : 'Enable alerts'}</span>
      </button>
    </div>
  )
}
import { useSyncExternalStore } from 'react'
import { call, type Mode, type Proposal, type WouldHandle } from './types'

// What the routines prepared for the buyer, shared by the Routines sheet, the decision pane and
// the inbox list: proposals waiting for an OK, routines that would handle a card, and actions
// undone on this screen. Refreshed on the app's own refresh (see `refreshLive`), never on its
// own timer. Endpoints that are not there yet (404) simply count as empty.

interface Live {
  proposals: Proposal[]
  would: Record<string, WouldHandle[]>
  /** Action id -> "undone" or the reason it could not be undone. */
  undo: Record<string, { ok: boolean; reason?: string }>
  /** Proposals the buyer just accepted or skipped, hidden before the server agrees. */
  settled: Set<string>
}

let live: Live = { proposals: [], would: {}, undo: {}, settled: new Set() }
const subs = new Set<() => void>()
const set = (next: Partial<Live>) => { live = { ...live, ...next }; subs.forEach((f) => f()) }
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f) } }

async function getJson<T>(url: string): Promise<T | null> {
  try {
    const r = await fetch(url)
    return r.ok ? ((await r.json()) as T) : null
  } catch { return null }
}

let lastAt = 0
let inflight: Promise<void> | null = null
/** Fetch proposals and would-handle; calls within `minMs` of the last one are skipped. */
export function refreshLive(minMs = 4000): Promise<void> {
  if (inflight) return inflight
  if (Date.now() - lastAt < minMs) return Promise.resolve()
  lastAt = Date.now()
  inflight = (async () => {
    const [p, w] = await Promise.all([
      getJson<{ proposals?: Proposal[] }>('/api/routines/proposals'),
      getJson<Record<string, WouldHandle[]>>('/api/routines/would-handle'),
    ])
    const proposals = Array.isArray(p?.proposals) ? p.proposals.filter((x) => x && x.id) : []
    const would: Record<string, WouldHandle[]> = {}
    for (const [k, v] of Object.entries(w ?? {})) if (Array.isArray(v) && v.length) would[k] = v
    // Forget settled ids the server no longer lists as pending.
    const pending = new Set(proposals.filter((x) => x.status === 'pending').map((x) => x.id))
    const settled = new Set([...live.settled].filter((id) => pending.has(id)))
    set({ proposals, would, settled })
  })().finally(() => { inflight = null })
  return inflight
}

export function useLive(): Live {
  return useSyncExternalStore(subscribe, () => live)
}

/** Pending proposals not yet answered on this screen; for one card when `cardId` is given. */
export function pendingOf(l: Live, cardId?: string): Proposal[] {
  return l.proposals.filter(
    (p) => (p.status ?? 'pending') === 'pending' && !l.settled.has(p.id) && (cardId == null || p.card_id === cardId),
  )
}

export async function answerProposal(id: string, how: 'accept' | 'skip'): Promise<void> {
  await call(`/api/routines/proposals/${encodeURIComponent(id)}/${how}`)
  // An accepted one stays a moment so its "Done" shows.
  window.setTimeout(() => {
    set({ settled: new Set(live.settled).add(id) })
    lastAt = 0
    void refreshLive()
  }, how === 'accept' ? 1500 : 0)
}

/** Undo a routine's action; remembers the outcome so the list and the pane agree. */
export async function undoAction(actionId: string): Promise<{ ok: boolean; reason?: string }> {
  let out: { ok: boolean; reason?: string }
  try {
    const r = await call<{ ok?: boolean; undone?: boolean; reason?: string }>(`/api/routines/actions/${encodeURIComponent(actionId)}/undo`)
    out = r.ok && r.undone !== false ? { ok: true } : { ok: false, reason: r.reason || 'This can no longer be undone.' }
  } catch (e) {
    const m = (e as Error).message
    out = { ok: false, reason: /404|not found/i.test(m) ? 'Undo is not available yet.' : m }
  }
  set({ undo: { ...live.undo, [actionId]: out } })
  return out
}

export async function setMode(routineId: string, mode: Mode): Promise<void> {
  await call(`/api/routines/${encodeURIComponent(routineId)}/mode`, { mode })
  lastAt = 0
  void refreshLive()
}

export async function setEnabled(routineId: string, enabled: boolean): Promise<void> {
  await call(`/api/routines/${encodeURIComponent(routineId)}/toggle`, { enabled })
  lastAt = 0
  void refreshLive()
}
import { Loader2, Undo2 } from 'lucide-react'
import { useState } from 'react'
import { cn } from '@/lib/utils'
import { undoAction, useLive } from './live'

// "Undo" for something a routine did on its own. The server decides whether it still can (an
// email that went out cannot be unsent); its reason shows in place of the button.

export function UndoAction({
  actionId, onUndone, className,
}: { actionId: string; onUndone?: () => void; className?: string }) {
  const live = useLive()
  const [busy, setBusy] = useState(false)
  const outcome = live.undo[actionId]

  if (outcome?.ok) {
    return <span className={cn('inline-flex items-center gap-1 text-xs font-semibold text-ink-3', className)}><Undo2 size={12} /> Undone</span>
  }
  return (
    <span className={cn('inline-flex min-w-0 flex-wrap items-center gap-x-2 gap-y-0.5', className)}>
      {!outcome && (
        <button
          type="button"
          disabled={busy}
          onClick={async (e) => {
            e.stopPropagation()
            setBusy(true)
            const out = await undoAction(actionId)
            setBusy(false)
            if (out.ok) onUndone?.()
          }}
          onKeyDown={(e) => e.stopPropagation()}
          className="inline-flex cursor-pointer items-center gap-1 rounded-md px-1.5 py-0.5 text-xs font-semibold text-ink-2 ring-1 ring-line hover:bg-white hover:text-ink disabled:opacity-60"
        >
          {busy ? <Loader2 size={12} className="animate-spin" /> : <Undo2 size={12} />} Undo
        </button>
      )}
      {outcome && !outcome.ok && <span className="text-xs font-medium text-stop">{outcome.reason}</span>}
    </span>
  )
}

